 for(const point of ['before-reserve','after-reserve','before-settle','after-settle'] as const){let calls=0;const f=await authorizedTaskFixture(async()=>({kind:'report',text:'unused'}));let fired=false;
  const store:MembershipTaskStore={...f.store,async commit(id,v,m){if(!fired&&((point==='before-reserve'&&m.usage?.status==='reserved')||(point==='after-reserve'&&m.event?.kind==='outbound')||(point==='before-settle'&&m.usage?.status==='settled')||(point==='after-settle'&&m.usage?.status==='settled'))){fired=true;if(point==='after-settle')await f.store.commit(id,v,m);throw Object.assign(Error('synthetic database response failure'),{code:point==='after-settle'?'RESULT_PENDING':'PUBLICATION_FAILED'});}return f.store.commit(id,v,m);}};
  const profile=syntheticProfile(),app=createMembershipTaskApplication({desktop:f.desktop,project_id:desktopTestIds.project,store,profile,modelAccess:f.shared,sourceStore:createLocalDesktopDecisionCaseStore({projectRoot:f.root}),runtime:createPiCaseAssistantRuntime({provider:'synthetic',model:'offline',max_input_bytes:profile.max_input_bytes,max_output_tokens:profile.call_output_tokens},{async respond(){calls++;return {kind:'question',text:'等待确认'};}})});
  await app.continue(f.id);await app.wait(f.id).catch(()=>undefined);const saved=await createLocalMembershipTaskStore(f.root).read(f.id);assert.equal(fired,true,point);assert.equal(calls,['before-reserve','after-reserve'].includes(point)?0:1,point);assert.equal(saved.usage.reduce((n,u)=>n+u.calls,0),['before-reserve','after-reserve'].includes(point)?0:1,point);assert.equal(saved.attempts.at(-1)?.status,'failed',`${point} must leave durable failed Attempt, not stuck Running`);assert.equal(f.shared.occupant?.(),null,point);
 }
