for(const effect of ['before','after'] as const)test(`P1-A-GRANT-FENCE-03 ${effect}-commit fault never admits a restored-source retry`,async()=>{
 let calls=0,drift=true,armed=true;const f=await authorizedTaskFixture(async()=>{throw Error('unused');}),sourceStore=createLocalDesktopDecisionCaseStore({projectRoot:f.root});
 const store:MembershipTaskStore={...f.store,async commit(id,v,m){if(armed&&m.fence){armed=false;if(effect==='after')await f.store.commit(id,v,m);throw Object.assign(Error('synthetic fence response fault'),{code:'RESULT_PENDING'});}return f.store.commit(id,v,m);}};
 const app=createMembershipTaskApplication({desktop:f.desktop,project_id:desktopTestIds.project,store,profile:syntheticProfile(),modelAccess:f.shared,runtime:{async turn(){calls++;throw Error('forbidden admission');}},sourceStore:{async readConfirmedSnapshot(x){const s=await sourceStore.readConfirmedSnapshot(x);return drift?{...s,snapshot:{...s.snapshot,orders:{...s.snapshot.orders,sha256:'0'.repeat(64)}}}:s;}}});
 await assert.rejects(()=>app.continue(f.id),{code:'RESULT_PENDING'});drift=false;let refused=false;try{await app.continue(f.id);}catch{refused=true;}await app.wait(f.id);assert.equal(refused,true,'unknown fence result closes admission even if source is restored');assert.equal(calls,0);await app.stop(f.id);assert.ok((await f.store.read(f.id)).grants[0].revoked_at);assert.equal((await f.store.read(f.id)).usage.length,0);
});

