for(const text of ['占比 50 % / 100 %','复购会员数（人） / 活跃会员数（人）','金额 100元 / 20人'])test(`F1-V4 Application preserves unit ratio through question reply report and expression comment: ${text}`,async()=>{
 const payloads:any[]=[];const f=await authorizedTaskFixture(async payload=>{payloads.push(JSON.parse(payload));return payloads.length===1?{kind:'question',text}:payloads.length===2?{kind:'tool',tool:'execute_plan'}:payloads.length===3?{kind:'report',text}:{kind:'comment',intent:'expression',text,periods:null};});
 const created=await f.app.create(text,randomUUID()),prepared=await f.app.prepare(created.task_id,f.input);await f.app.authorize(created.task_id,{fingerprint:prepared.prepared!.fingerprint,source_files:f.input.source_files,authority_confirmed:true,text_consent:true});await f.app.continue(created.task_id);await until(async()=>(await f.app.read(created.task_id)).status==='waiting');assert.equal(payloads[0].selected_text,text);await f.app.reply(created.task_id,text,true);let p=await f.app.wait(created.task_id);assert.equal(payloads[1].selected_text,text);assert.equal(p.attempts.at(-1)!.status,'succeeded');assert.ok(p.events.some(e=>e.kind==='explanation'&&e.text===text));const report=p.case.reports[0],id=randomUUID();await f.app.comment(created.task_id,{id,report_id:report.report_id,report_version:report.version_sequence,report_sha256:report.markdown_sha256,scope:'expression',author:'合成人员',text,text_consent:true});await f.app.processComment(created.task_id,id);p=await f.app.wait(created.task_id);assert.equal(payloads.at(-1).selected_text,text);assert.equal(p.comments.at(-1)!.resolution!.text,text);assert.equal(p.case.reports.length,2);assert.deepEqual(p.case.reports[0],report);
});
for(const text of ['占比 50 % / 100 %','复购会员数（人） / 活跃会员数（人）','金额 100元 / 20人'])test(`F1-V4 retained Application preserves unit ratio in main return and selected history: ${text}`,async()=>{
 const payloads:any[]=[];const f=await retainedFixture(async p=>{payloads.push(JSON.parse(p));return {kind:'advice',text};}),id=f.parent.session.id;
 const a=await f.retained.prepare(id,text);await f.retained.start(id,a.id,true);const first=await f.wait();assert.equal(first.attempts.at(-1)!.status,'Succeeded');const advice=first.events.find(e=>e.kind==='advice'&&e.text===text)!;assert.ok(advice);assert.equal(payloads[0].visible_message,text);const b=await f.retained.prepare(id,text,[advice.id]);await f.retained.start(id,b.id,true);await f.wait();assert.equal(payloads[1].authorized_context.selected_history[0].text,text);assert.equal(payloads[1].visible_message,text);await f.retained.close();
});

